const body = $input.first().json.body || {};
const timestamp = body.timestamp || new Date().toISOString();
const reply = String(body.reply ?? '').trim();
const userMessage = String(body.userMessage ?? '').trim();
const emotion = body.emotion ?? { label: 'neutral', confidence: 0 };
const affinity = body.affinity ?? { score: 0, stage: 'desconhecido' };
const actions = body.actions ?? [];
const source = body.source ?? 'desconhecido';

if (!reply && !userMessage) {
  throw new Error('Evento sem conteúdo (reply ou userMessage).');
}

const createdAt = new Date(timestamp).toISOString();
const ts = createdAt.replace(/[:.]/g, '-');
const slug = (userMessage || reply).slice(0, 60)
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 60) || 'evento';
const filename = `${ts}-${slug}.md`;

const actionSummary = actions
  .map(a => `- ${a.type}: ${a.name ?? ''}${a.value !== undefined ? ' → ' + a.value : ''}${a.delayMs !== undefined ? ' (+' + a.delayMs + 'ms)' : ''}`)
  .join('\n') || '(nenhuma ação)';
const markdown = `---\nsource: usami-response\nkind: chat-reply\ncreated_at: ${createdAt}\nuser_message: ${JSON.stringify(userMessage)}\nemotion_label: ${JSON.stringify(emotion?.label ?? 'neutral')}\nemotion_confidence: ${emotion?.confidence ?? 0}\naffinity_score: ${affinity?.score ?? 0}\naffinity_stage: ${JSON.stringify(affinity?.stage ?? 'desconhecido')}\nresponse_source: ${JSON.stringify(source)}\nactions_count: ${actions.length}\n---\n\n## Resposta da Usami\n\n${reply || '(sem texto)'}\n\n## Ações de animação\n\n${actionSummary}\n\n---\n_Evento recebido via webhook usami-events às ${createdAt}_\n`;

return [{ json: { filename, markdown, userMessage, reply, emotion, affinity, actions, source, timestamp: createdAt } }];
